package com.dronefleet.repository;
import java.sql.*;
public final class AuditRepository {private final com.dronefleet.config.Database db;public AuditRepository(com.dronefleet.config.Database db){this.db=db;}public void log(String user,String action,String type,String id,String details){try(Connection c=db.connect();PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(username,action,entity_type,entity_id,details,created_at) VALUES(?,?,?,?,?,?)")){p.setString(1,user);p.setString(2,action);p.setString(3,type);p.setString(4,id);p.setString(5,details);p.setString(6,java.time.LocalDateTime.now().toString());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}public java.util.List<String> recent(int limit){java.util.List<String> x=new java.util.ArrayList<>();try(Connection c=db.connect();PreparedStatement p=c.prepareStatement("SELECT created_at,username,action,entity_type,entity_id,details FROM audit_log ORDER BY id DESC LIMIT ?")){p.setInt(1,limit);try(ResultSet r=p.executeQuery()){while(r.next())x.add(r.getString(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | "+r.getString(4)+"#"+r.getString(5)+" | "+r.getString(6));}}catch(SQLException e){throw new RuntimeException(e);}return x;}}
